 if(name==='delete'){const l=lesson(),attempts=findAttempts(l.id);modal(tr('حذف الدرس والبيانات المرتبطة','Delete lesson and related data'),`<p>${tr('لن تُحذف الملاحظة أو PDF الأصلي المرتبط. اختر المحاولات التي تريد الاحتفاظ بنتائجها وملاحظاتها وتسجيلاتها. الملفات المحلية المحذوفة لا يمكن استعادتها.','The linked original note/PDF remains. Choose attempts whose results, notes and audio to retain. Deleted local files cannot be recovered.')}</p><select name="mode"><option value="keep">${tr('حذف الدرس مع الاحتفاظ بالمحاولات المحددة فقط','Delete lesson and retain only selected attempts')}</option><option value="all">${tr('حذف الدرس وكل البيانات التابعة له','Delete lesson and all its related data')}</option></select>${attempts.map(r=>`<label><input type="checkbox" name="keep" value="${r.id}" checked>${esc(r.data.title)} · ${date(r.data.study.created)} · ${esc(label(r.data.study.status))}</label>`).join('')}`,async f=>{const keep=new Set(f.get('mode')==='all'?[]:f.getAll('keep')),ids=new Set([l.id,...entity('version').filter(v=>v.data.study.lessonId===l.id).map(v=>v.id)]),files=[];for(const r of attempts){const a=r.data.study;if(keep.has(r.id)){const v=data(a.versionId);a.pagesSnapshot ||=structuredClone(v?.pages||[]);a.imagesSnapshot=structuredClone(v?.images||a.imagesSnapshot||[]);a.unitsSnapshot=structuredClone(currentUnits(a));a.retainedAfterLessonDeletion=true;touch(r)}else{ids.add(r.id);if(a.noteId)ids.add(a.noteId);if(a.errorSummaryId)ids.add(a.errorSummaryId);for(const seg of a.segments||[])files.push(...seg.parts||[]);for(const img of a.imagesSnapshot||[])files.push(img.id)}}for(const id of ids)for(const img of get(id)?.data.study?.images||[])files.push(img.id);await eraseRecords(ids,files);closeModal();selected=null;attemptId=null;pane='library';draw()});return}
