 document.addEventListener('click',e=>{const b=e.target.closest('[data-study-action]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();Promise.resolve(action(b.dataset.studyAction,b)).catch(error)},true);
 window.addEventListener('online',()=>processQueue().catch(error));
 setInterval(()=>{if(host.owner()===scopeOwner)notifyDue().catch(()=>{})},60000);
 return{async copyWorkspace(from,to,rows){const ids=new Set();for(const r of rows.filter(r=>!r.deleted)){for(const image of [...r.data.study?.images||[],...r.data.study?.imagesSnapshot||[]])ids.add(image.id);for(const segment of r.data.study?.segments||[])for(const id of segment.parts||[])ids.add(id)}let missing=0;for(const id of ids){let blob;try{blob=await loadMedia(from,id)}catch{missing++;continue}await saveMedia(to,id,blob)}if(missing)host.toast(tr('استوردت النصوص؛ بعض الملفات غير موجودة على هذا الجهاز.','Text imported; some media is unavailable on this device.'))},view,mount(){if(scopeOwner!==host.owner()){controller?.abort();recorder?.release();recorder=null;scopeOwner=host.owner();pane='library';selected=null;attemptId=null;editor=null}draw()},active,busy:()=>pending||processing||!!stopping,async startFromNote(note){host.showStudy();newEditor();editor.title=note.data.title;editor.sourceRef=note.id;editor.sourceType=note.data.pdf?'pdf':'note';editor.text=note.data.text||'';draw()},async leave(){if(active())return sourceGuard();await discardEditor();return true},async close(){controller?.abort();await stopRecorder();await discardEditor();urls.forEach(URL.revokeObjectURL);urls=[];scopeOwner='';pane='library';attemptId=null},resumeQueue:processQueue,async noteAttachment(note){const link=note.data.studyAttempt||note.data.studyErrorSummary;if(!link)return '';const r=get(link.attemptId);if(!r)return '';return `<section class="study-note-links"><p>${tr('الإجابة الأصلية والتقييم ثابتان في سجل المحاولة، وتعديل هذه الملاحظة لا يغيرهما.','The assessed answer is frozen in its attempt history. Editing this note does not change it.')}</p>${button('attempt',tr('تقرير التقييم والتسجيلات','Assessment report & audio'),'soft',`data-id="${r.id}"`)}</section>`},attachmentHtml(note){const link=note.data.studyAttempt||note.data.studyErrorSummary;if(!link)return '';return `<section class="study-note-links">${note.data.studyErrorSummary?`<p>${tr('ملخص أخطاء مرتبط بتقييم','Mistakes summary from assessment')}: ${date(link.evaluationAt)}</p>`:''}<p>${data(link.attemptId)?.evaluations?.at(-1)?.grade?data(link.attemptId).evaluations.at(-1).grade.score+'/50':tr('بانتظار التقييم','Awaiting assessment')}</p>${button('attempt',tr('تقرير التقييم والتسجيلات','Assessment report & audio'),'soft',`data-id="${esc(link.attemptId)}"`)}<p class="hint">${tr('تعديل الملاحظة لا يغير الإجابة الأصلية المقيمة.','Editing this note does not change the frozen assessed answer.')}</p><div id="study-note-audio"></div><details><summary>${tr('معاينة منسقة للنص','Formatted text preview')}</summary><div id="study-note-preview" class="message-content">${formatMathMessage(note.data.text||'')}</div></details>${get(link.lessonId)?button('lesson',tr('الدرس الأصلي','Original lesson'),'soft',`data-id="${esc(link.lessonId)}"`):''}</section>`},async mountNote(note){const a=data((note?.data.studyAttempt||note?.data.studyErrorSummary)?.attemptId),root=document.querySelector('#study-note-audio');if(!a||!root)return;root.innerHTML=(a.segments||[]).filter(s=>s.type==='audio'&&!s.mediaDeleted).map(s=>`<audio controls preload="none" data-study-audio="${esc(s.id)}"></audio>`).join('');await mountMediaForNote(root,a);renderMessageMath(document.querySelector('#study-note-preview'),lang())},openAttempt(id){attemptId=id;selected=data(id)?.lessonId;pane=data(id)?.status==='active'?'session':'report';host.showStudy();draw()}};
 async function mountMediaForNote(root,a){for(const audio of root.querySelectorAll('[data-study-audio]')){try{const seg=a.segments.find(s=>s.id===audio.dataset.studyAudio),blob=await audioBlob(host.owner(),seg);if(!audio.isConnected)continue;const url=URL.createObjectURL(blob);urls.push(url);audio.src=url}catch{audio.replaceWith(document.createTextNode(tr('التسجيل على الجهاز الأصلي','Recording on original device')))}}}
